// Turn each CSV row into a request for the agent API, and keep the expected answers for scoring
return $input.all().map(item => {
  const row = item.json;
  return {
    json: {
      case_id: row.case_id,
      language: row.language,
      scenario: row.scenario,
      expected_claim_type: row.expected_claim_type,
      expected_decision: row.expected_decision,
      request: {
        claim_id: 'EVAL-' + row.case_id,
        policy_number: row.policy_number,
        description: row.description,
        transcript: row.transcript || '',
        damage_report: JSON.parse(row.damage_report),
        incident_date: '2026-11-04',          // fixed date, so results are repeatable
      },
    },
  };
});

// Compare each agent answer with the expected answer (results come back in the same order as the requests)
const cases = $('Build Requests').all();

return $input.all().map((item, i) => {
  const expected = cases[i].json;
  const result = item.json;
  const predictedType = result.classification ? result.classification.claim_type : '';
  return {
    json: {
      case_id: expected.case_id,
      language: expected.language,
      scenario: expected.scenario,
      expected_claim_type: expected.expected_claim_type,
      predicted_claim_type: predictedType,
      classifier_method: result.classification ? result.classification.method : '',
      confidence: result.classification ? result.classification.confidence : '',
      expected_decision: expected.expected_decision,
      predicted_decision: result.decision || 'error',
      type_correct: predictedType === expected.expected_claim_type,
      decision_correct: result.decision === expected.expected_decision,
      payable_amount: result.payable_amount,
      cited_clauses: (result.clauses || []).map(c => c.clause).join(', '),
      trace_id: result.trace_id || '',
    },
  };
});

// One summary of the whole evaluation
const rows = $input.all().map(item => item.json);
const percent = (part, total) => total ? Math.round(part / total * 1000) / 10 : 0;
const count = (list, test) => list.filter(test).length;

const typed = rows.filter(r => r.expected_decision !== 'need_more_info');   // unknown policy has no claim type check
const english = rows.filter(r => r.language === 'en');
const hinglish = rows.filter(r => r.language === 'hinglish');

return [{
  json: {
    total_cases: rows.length,
    decision_accuracy_percent: percent(count(rows, r => r.decision_correct), rows.length),
    claim_type_accuracy_percent: percent(count(typed, r => r.type_correct), typed.length),
    english_decision_accuracy_percent: percent(count(english, r => r.decision_correct), english.length),
    hinglish_decision_accuracy_percent: percent(count(hinglish, r => r.decision_correct), hinglish.length),
    handled_by_fine_tuned_model: count(rows, r => r.classifier_method === 'fine_tuned_model'),
    handled_by_gpt_fallback: count(rows, r => r.classifier_method === 'gpt_fallback'),
    wrong_cases: rows.filter(r => !r.decision_correct || (r.expected_decision !== 'need_more_info' && !r.type_correct))
                     .map(r => `${r.case_id}: expected ${r.expected_decision}/${r.expected_claim_type}, got ${r.predicted_decision}/${r.predicted_claim_type}`),
  },
}];
